package com.codeguardian.service.tools; import com.codeguardian.entity.Finding; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.util.*; @Service @RequiredArgsConstructor public class AgenticWorkflow{private final JavaParserAnalysisTool parser;private final SemgrepAnalysisTool semgrep;public List<Finding> inspect(String code,String language,boolean useSemgrep){ReviewContextHolder.clear();List<Finding> out=new ArrayList<>();if("JAVA".equalsIgnoreCase(language))out.addAll(parser.analyze(code));if(useSemgrep)out.addAll(semgrep.analyze(code));ReviewContextHolder.addAll(out);return out;}}
